import{_ as a,o as t,c as l,ag as i}from"./chunks/framework.DTisvaUJ.js";const m=JSON.parse('{"title":"更新记录","description":"Mutelink更新记录，包含识别、朗读、翻译、VR键盘等主要新增与修复。","frontmatter":{"description":"Mutelink更新记录，包含识别、朗读、翻译、VR键盘等主要新增与修复。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/changelog"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"更新记录 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink更新记录，包含识别、朗读、翻译、VR键盘等主要新增与修复。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/about/changelog"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"更新记录 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink更新记录，包含识别、朗读、翻译、VR键盘等主要新增与修复。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/changelog"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/changelog"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/changelog"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}]]},"headers":[],"relativePath":"zh/about/changelog.md","filePath":"zh/about/changelog.md"}'),n={name:"zh/about/changelog.md"};function r(o,e,h,u,s,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="更新履歴" tabindex="-1">更新记录 <a class="header-anchor" href="#更新履歴" aria-label="Permalink to &quot;更新记录 {#更新履歴}&quot;">​</a></h1><p>仅列主要更新，新版本在前。安装程序见<a href="https://github.com/utyujinn/Mutelink-releases/releases" target="_blank" rel="noreferrer">Releases</a>。</p><h2 id="v2-0-0-2026年11月15日" tabindex="-1">v2.0.0（2026年11月15日） <a class="header-anchor" href="#v2-0-0-2026年11月15日" aria-label="Permalink to &quot;v2.0.0（2026年11月15日） {#v2-0-0-2026年11月15日}&quot;">​</a></h2><p>大幅重新设计界面和功能。</p><h3 id="画面" tabindex="-1">界面 <a class="header-anchor" href="#画面" aria-label="Permalink to &quot;界面 {#画面}&quot;">​</a></h3><ul><li>全面更新界面和操作。</li></ul><h3 id="読み上げ" tabindex="-1">朗读 <a class="header-anchor" href="#読み上げ" aria-label="Permalink to &quot;朗读 {#読み上げ}&quot;">​</a></h3><ul><li>大幅降低Irodori-TTS显存用量并提高速度。</li><li>新增Qwen3-TTS，支持日语及其他9种语言（<a href="/Mutelink-releases/zh/compare/voices">声音试听</a>）。</li></ul><h3 id="音声認識" tabindex="-1">语音识别 <a class="header-anchor" href="#音声認識" aria-label="Permalink to &quot;语音识别 {#音声認識}&quot;">​</a></h3><ul><li>更新本地识别模型，大幅提升日语识别准确度（Parakeet日语TDT、Haas-ja、Qwen3-ASR；<a href="/Mutelink-releases/zh/compare/speech-recognition">对比</a>）。</li></ul><h3 id="翻訳" tabindex="-1">翻译 <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;翻译 {#翻訳}&quot;">​</a></h3><ul><li>可翻译自己的话并通过声音或聊天框发送。</li><li>可阅读对方语音的译文。</li><li>可选择PLaMo、TranslateGemma或Azure Translator云翻译（<a href="/Mutelink-releases/zh/compare/translation">对比</a>）。</li></ul><h3 id="vrキーボード" tabindex="-1">VR键盘 <a class="header-anchor" href="#vrキーボード" aria-label="Permalink to &quot;VR键盘 {#vrキーボード}&quot;">​</a></h3><ul><li>支持4种日语、4种中文、2种韩语输入方式，以及英语、符号和模板。</li><li>支持滑行输入。</li></ul><h3 id="そのほか" tabindex="-1">其他 <a class="header-anchor" href="#そのほか" aria-label="Permalink to &quot;其他 {#そのほか}&quot;">​</a></h3><ul><li>新增对方说话时等待、不立即发声的功能（可开关）。</li><li>可设置在声音开始播放时显示聊天框文字（可开关）。</li><li>控制面板与键盘分离，可附着到手上（需自定义扩展）。</li></ul><h2 id="v1-0-3-2026年11月5日" tabindex="-1">v1.0.3（2026年11月5日） <a class="header-anchor" href="#v1-0-3-2026年11月5日" aria-label="Permalink to &quot;v1.0.3（2026年11月5日） {#v1-0-3-2026年11月5日}&quot;">​</a></h2><ul><li>修复Parakeet、Whisper和Google识别中音频重叠或缺失的问题。</li></ul><h2 id="v1-0-2-2026年10月18日" tabindex="-1">v1.0.2（2026年10月18日） <a class="header-anchor" href="#v1-0-2-2026年10月18日" aria-label="Permalink to &quot;v1.0.2（2026年10月18日） {#v1-0-2-2026年10月18日}&quot;">​</a></h2><ul><li>可自定义拇指下侧按钮的单击动作。</li><li>新增匿名向作者发送问题与建议的功能。</li><li>更新后首次启动显示变更内容。</li><li>操作失败时显示错误提示。</li></ul><h2 id="v1-0-1-2026年10月16日" tabindex="-1">v1.0.1（2026年10月16日） <a class="header-anchor" href="#v1-0-1-2026年10月16日" aria-label="Permalink to &quot;v1.0.1（2026年10月16日） {#v1-0-1-2026年10月16日}&quot;">​</a></h2><ul><li>修复VR背景图片添加及加载问题。</li><li>新增启动时通知更新的设置。</li></ul><h2 id="v1-0-0-2026年10月10日" tabindex="-1">v1.0.0（2026年10月10日） <a class="header-anchor" href="#v1-0-0-2026年10月10日" aria-label="Permalink to &quot;v1.0.0（2026年10月10日） {#v1-0-0-2026年10月10日}&quot;">​</a></h2><p>首个正式版本。</p>',24)])])}const p=a(n,[["render",r]]);export{m as __pageData,p as default};
